<?php
require_once __DIR__.'/app.php';
function admin_required():void{if(empty($_SESSION['admin_id'])){flash('Connectez-vous pour accéder à l’administration.','error');redirect('login.php');}}
function render_admin_header(string $title):void{$n=take_flash();?><!doctype html><html lang="fr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?=e($title)?> · Administration</title><link rel="icon" href="../assets/img/favicon.svg" type="image/svg+xml"><link rel="stylesheet" href="../assets/css/style.css"><script defer src="../assets/js/app.js"></script></head><body class="admin-body"><header class="admin-header"><div class="container admin-header-inner"><a class="brand" href="index.php"><span class="brand-mark">E</span><span>Administration<small>Gestion de la boutique</small></span></a><nav><a href="../index.php" target="_blank">Voir la boutique ↗</a><a href="logout.php">Déconnexion</a></nav></div></header><main class="container admin-main"><?php if($n):?><div class="notice <?=e($n['type'])?>"><?=e($n['message'])?></div><?php endif;?><?php}
function render_admin_footer():void{?></main></body></html><?php}
function save_product_image(array $file,?string $old=null):?string{if(($file['error']??UPLOAD_ERR_NO_FILE)===UPLOAD_ERR_NO_FILE)return $old;if(($file['error']??UPLOAD_ERR_OK)!==UPLOAD_ERR_OK)throw new RuntimeException('Téléversement impossible.');if(($file['size']??0)>MAX_UPLOAD_BYTES)throw new RuntimeException('Image limitée à 5 Mo.');$mime=(new finfo(FILEINFO_MIME_TYPE))->file($file['tmp_name']);$ext=['image/jpeg'=>'jpg','image/png'=>'png','image/webp'=>'webp'];if(!isset($ext[$mime])||@getimagesize($file['tmp_name'])===false)throw new RuntimeException('Format JPG, PNG ou WEBP requis.');$dir=dirname(__DIR__).'/uploads';if(!is_dir($dir)&&!mkdir($dir,0755,true))throw new RuntimeException('Création du dossier impossible.');$name=bin2hex(random_bytes(16)).'.'.$ext[$mime];if(!move_uploaded_file($file['tmp_name'],$dir.'/'.$name))throw new RuntimeException('Enregistrement de l’image impossible.');if($old&&str_starts_with($old,'uploads/'))@unlink(dirname(__DIR__).'/'.$old);return 'uploads/'.$name;}
function valid_product_input(array $i):array{$n=trim((string)($i['name']??''));$c=trim((string)($i['category']??''));$d=trim((string)($i['description']??''));$p=filter_var($i['price']??null,FILTER_VALIDATE_FLOAT);$s=filter_var($i['stock']??null,FILTER_VALIDATE_INT);if($n===''||mb_strlen($n)>160)throw new RuntimeException('Nom obligatoire (160 caractères maximum).');if($c===''||mb_strlen($c)>80)throw new RuntimeException('Catégorie obligatoire.');if($p===false||$p<0||$p>999999999)throw new RuntimeException('Prix invalide.');if($s===false||$s<0||$s>1000000)throw new RuntimeException('Stock invalide.');return ['name'=>$n,'category'=>$c,'description'=>$d,'price'=>$p,'stock'=>$s];}
